"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[960],{770:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-09-pca-svd-mds</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-9-метод-главных-компонент-svd-и-многомерное-шкалирование">Лабораторная\nработа 9. Метод главных компонент, SVD и многомерное шкалирование</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 8, завершает курс</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 8: выборочная ковариационная матрица (опр. 8.1), первая\nглавная компонента (теорема 8.2), полная дисперсия (утв. 8.5), доля\nобъяснённой дисперсии, численный пример 8.7, сингулярное разложение\n(теорема 8.9) и его связь с PCA, многомерное шкалирование; лекции 2 и 4:\nобусловленность, скользящий контроль</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно (части 1–3) + 6 ч самостоятельно</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Реализовать PCA двумя способами — через собственные векторы\nковариационной матрицы и через SVD — и убедиться, что это одно и то же;\nпроверить утверждения лекции 8 численно на примере из конспекта;\nприменить PCA к сжатию изображений и к предобработке перед\nклассификатором; понять, почему масштабирование меняет результат PCA;\nпостроить карту объектов по одним лишь попарным расстояниям (MDS).\nПоследняя часть — сводная: полный цикл работы с данными на своём\nварианте.</p>\n<h2 id="что-нужно-сдать">Что нужно сдать</h2>\n<p>Заполненный ноутбук <code>lab09_student.ipynb</code>, в котором:</p>\n<ol>\n<li>выполнены все задания (ячейки с <code># TODO</code>), код\nзапускается сверху вниз без ошибок;</li>\n<li>под каждым заданием заполнены ячейки <strong>Вывод</strong> — своими\nсловами, не пересказ кода;</li>\n<li>в конце — раздел «Итоги работы» с ответами на контрольные\nвопросы;</li>\n<li>все графики подписаны (заголовок, оси, легенда).</li>\n</ol>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже). Отчёт с чужим вариантом не\nпринимается.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> linalg</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> load_digits, load_iris, load_wine</span>\n<span id="cb1-48"><a href="#cb1-48" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.decomposition <span class="im">import</span> PCA</span>\n<span id="cb1-49"><a href="#cb1-49" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> GridSearchCV, StratifiedKFold, cross_val_score, train_test_split</span>\n<span id="cb1-50"><a href="#cb1-50" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> RobustScaler, StandardScaler</span>\n<span id="cb1-51"><a href="#cb1-51" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span>\n<span id="cb1-52"><a href="#cb1-52" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-53"><a href="#cb1-53" aria-hidden="true" tabindex="-1"></a><span class="co"># SelectKBest предупреждает о константных пикселях в digits (их 3 из 64) --</span></span>\n<span id="cb1-54"><a href="#cb1-54" aria-hidden="true" tabindex="-1"></a><span class="co"># предупреждение ожидаемо и на результат не влияет.</span></span>\n<span id="cb1-55"><a href="#cb1-55" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, message<span class="op">=</span><span class="st">&quot;.*are constant.*&quot;</span>)</span>\n<span id="cb1-56"><a href="#cb1-56" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">RuntimeWarning</span>, message<span class="op">=</span><span class="st">&quot;.*invalid value.*&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell002" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell003" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">9</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell004" class="cell markdown">\n<hr />\n<h1 id="часть-1-pca-два-вывода-одного-результата">Часть 1. PCA: два\nвывода одного результата</h1>\n<p>Определение 8.1: выборочная ковариационная матрица центрированных\nданных</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>C</mi><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><msub><mi>x</mi><mi>i</mi></msub><msubsup><mi>x</mi><mi>i</mi><mi>𝖳</mi></msubsup><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mi>.</mi></mrow><annotation encoding="application/x-tex">\nC = \\frac1\\ell\\sum_{i=1}^{\\ell} x_i x_i^{\\mathsf T} = \\frac1\\ell X^{\\mathsf T}X .\n</annotation></semantics></math></p>\n<p>Теорема 8.2: первая главная компонента — собственный вектор\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>,\nотвечающий наибольшему собственному числу, а дисперсия проекции равна\nэтому собственному числу. Утверждение 8.5:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mo>∑</mo><mi>j</mi></msub><msub><mi>λ</mi><mi>j</mi></msub><mo>=</mo><mrow><mi mathvariant="normal">T</mi><mi mathvariant="normal">r</mi></mrow><mspace width="0.167em"></mspace><mi>C</mi></mrow><annotation encoding="application/x-tex">\\sum_j \\lambda_j = \\mathrm{Tr}\\,C</annotation></semantics></math>\n— полная дисперсия.</p>\n<p>Второй путь (теорема 8.9):\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi><mo>=</mo><mi>U</mi><mi mathvariant="normal">Σ</mi><msup><mi>V</mi><mi>𝖳</mi></msup></mrow><annotation encoding="application/x-tex">X = U\\Sigma V^{\\mathsf T}</annotation></semantics></math>,\nи тогда\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo>=</mo><mi>V</mi><msup><mi mathvariant="normal">Σ</mi><mn>2</mn></msup><msup><mi>V</mi><mi>𝖳</mi></msup></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X = V\\Sigma^2V^{\\mathsf T}</annotation></semantics></math>,\nто есть <strong>правые сингулярные векторы\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>V</mi><annotation encoding="application/x-tex">V</annotation></semantics></math>\n— это главные компоненты</strong>, а\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>λ</mi><mi>j</mi></msub><mo>=</mo><msubsup><mi>σ</mi><mi>j</mi><mn>2</mn></msubsup><mi>/</mi><mi>ℓ</mi></mrow><annotation encoding="application/x-tex">\\lambda_j = \\sigma_j^2/\\ell</annotation></semantics></math>.\nНа практике всегда используют SVD: он не требует явно строить\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\nи не возводит обусловленность в квадрат (работа 2, часть 4.2).</p>\n<p>Начнём с точного воспроизведения примера 8.7 из лекции.</p>\n</div>\n<div id="cell005" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="kw">class</span> MyPCA:</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;PCA двумя способами: &#39;eig&#39; -- через собственные векторы C, &#39;svd&#39; -- через SVD.</span></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a><span class="co">    fit: центрировать; для &#39;eig&#39; построить C = X^T X / l и взять np.linalg.eigh,</span></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a><span class="co">         для &#39;svd&#39; -- np.linalg.svd, при этом lambda_j = sigma_j^2 / l,</span></span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a><span class="co">         а главные компоненты -- строки Vt.</span></span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a><span class="co">         Не забудьте отсортировать по убыванию и зафиксировать знак векторов.</span></span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a><span class="co">    transform / inverse_transform.</span></span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a><span class="co">    Сохраните explained_variance_, explained_variance_ratio_, total_variance_.</span></span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb3-11"><a href="#cb3-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-12"><a href="#cb3-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-13"><a href="#cb3-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-14"><a href="#cb3-14" aria-hidden="true" tabindex="-1"></a><span class="co"># Пример 8.7 из лекции: четыре центрированные точки</span></span>\n<span id="cb3-15"><a href="#cb3-15" aria-hidden="true" tabindex="-1"></a>X_ex <span class="op">=</span> np.array([[<span class="fl">2.0</span>, <span class="fl">1.0</span>], [<span class="op">-</span><span class="fl">1.0</span>, <span class="op">-</span><span class="fl">2.0</span>], [<span class="fl">1.0</span>, <span class="fl">2.0</span>], [<span class="op">-</span><span class="fl">2.0</span>, <span class="op">-</span><span class="fl">1.0</span>]])</span>\n<span id="cb3-16"><a href="#cb3-16" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-17"><a href="#cb3-17" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) постройте C, выведите её след и определитель;</span></span>\n<span id="cb3-18"><a href="#cb3-18" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) обоими способами найдите собственные числа и первую компоненту --</span></span>\n<span id="cb3-19"><a href="#cb3-19" aria-hidden="true" tabindex="-1"></a><span class="co">#          сверьте с лекцией: lambda = 4.5 и 0.5, w_1 = (1,1)/sqrt(2), доля 0.9;</span></span>\n<span id="cb3-20"><a href="#cb3-20" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) спроецируйте на первую компоненту, восстановите точки и сверьте</span></span>\n<span id="cb3-21"><a href="#cb3-21" aria-hidden="true" tabindex="-1"></a><span class="co">#          суммарную ошибку с теоретической lambda_2 * l = 2.</span></span></code></pre></div>\n</div>\n<div id="cell006" class="cell markdown">\n<h3 id="задание-12-сверка-со-sklearn-и-цена-явного-построения-c">Задание\n1.2. Сверка со <code>sklearn</code> и цена явного построения\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math></h3>\n<p>Сравните оба своих метода со <code>sklearn.decomposition.PCA</code>\nна реальных данных, а затем проверьте численное преимущество SVD:\nпостройте плохо обусловленную матрицу (как в работе 2) и сравните\nточность обоих подходов.</p>\n</div>\n<div id="cell007" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a>X_w, y_w <span class="op">=</span> load_wine(return_X_y<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a>X_ws <span class="op">=</span> StandardScaler().fit_transform(X_w)</span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) сверьте оба своих метода со sklearn.decomposition.PCA</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a><span class="co">#          (внимание: sklearn делит на l-1, лекция -- на l);</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) сравните точность &#39;eig&#39; и &#39;svd&#39; на матрицах с cond от 1e2 до 1e10</span></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a><span class="co">#          (стройте их через SVD с заданными сингулярными числами, как в работе 3;</span></span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a><span class="co">#          матрицу центрируйте ДО построения, иначе спектр изменится).</span></span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a><span class="co">#          Смотрите на относительную ошибку САМОГО МАЛОГО собственного числа;</span></span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) постройте scree-plot и график накопленной доли дисперсии,</span></span>\n<span id="cb4-11"><a href="#cb4-11" aria-hidden="true" tabindex="-1"></a><span class="co">#          отметьте пороги 90% и 95%.</span></span>\n<span id="cb4-12"><a href="#cb4-12" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;правило вашего варианта:&quot;</span>, variant[<span class="st">&quot;n_components_rule&quot;</span>])</span></code></pre></div>\n</div>\n<div id="cell008" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпали ли оба метода со\n<code>sklearn</code>? С какого числа обусловленности подход через\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\nначинает терять точность и почему? Сколько компонент нужно для 95 %\nдисперсии на <code>wine</code> и что это говорит о данных?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell009" class="cell markdown">\n<hr />\n<h1 id="часть-2-масштабирование-меняет-ответ-pca">Часть 2.\nМасштабирование меняет ответ PCA</h1>\n<p>PCA ищет направления максимальной дисперсии, а дисперсия зависит от\nединиц измерения. Признак «доход в рублях» имеет дисперсию в миллиарды\nраз большую, чем «доля клиентов», и первая главная компонента совпадёт с\nним почти точно — независимо от содержательной важности.</p>\n<p>Ваш вариант: <code>variant[&quot;scaling&quot;]</code>. Сравните PCA до и после\nмасштабирования.</p>\n</div>\n<div id="cell010" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: сравните PCA при двух вариантах масштабирования из своего варианта:</span></span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       для каждого нарисуйте проекцию на первые две компоненты (раскрасив</span></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       по классам), выведите долю дисперсии PC1 и три признака с наибольшими</span></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a><span class="co">#       по модулю коэффициентами в PC1. Сопоставьте с разбросом исходных признаков.</span></span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;сравнение вашего варианта:&quot;</span>, variant[<span class="st">&quot;scaling&quot;</span>])</span></code></pre></div>\n</div>\n<div id="cell011" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какой признак «захватил» первую компоненту\nбез масштабирования и почему? Всегда ли нужно стандартизовать перед\nPCA?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell012" class="cell markdown">\n<hr />\n<h1 id="часть-3-сжатие-и-восстановление">Часть 3. Сжатие и\nвосстановление</h1>\n<p>Теорема Эккарта–Янга (следствие из теоремы 8.9): усечённое SVD ранга\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\n— <strong>наилучшее</strong> приближение матрицы рангом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nв норме Фробениуса, причём</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><munder><mi>min</mi><mrow><mrow><mi mathvariant="normal">r</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">k</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>B</mi><mo stretchy="false" form="postfix">)</mo><mo>≤</mo><mi>k</mi></mrow></munder><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mo>−</mo><mi>B</mi><msubsup><mo stretchy="false" form="postfix">∥</mo><mi>F</mi><mn>2</mn></msubsup><mspace width="0.278em"></mspace><mo>=</mo><mspace width="0.278em"></mspace><munder><mo>∑</mo><mrow><mi>j</mi><mo>&gt;</mo><mi>k</mi></mrow></munder><msubsup><mi>σ</mi><mi>j</mi><mn>2</mn></msubsup><mo>,</mo></mrow><annotation encoding="application/x-tex">\n\\min_{\\mathrm{rank}(B) \\le k}\\|X - B\\|_F^2 \\;=\\; \\sum_{j &gt; k}\\sigma_j^2 ,\n</annotation></semantics></math></p>\n<p>то есть ошибка равна сумме квадратов <strong>отброшенных</strong>\nсингулярных чисел. Проверьте это равенство численно и посмотрите на\nсжатие изображений.</p>\n</div>\n<div id="cell013" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a>digits <span class="op">=</span> load_digits()</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>X_dig <span class="op">=</span> digits.data</span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) проверьте теорему Эккарта--Янга: для k = 1, 5, 10, 20, 40 сравните</span></span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a><span class="co">#          ||X - X_k||_F^2 с суммой квадратов отброшенных сингулярных чисел;</span></span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) покажите восстановление нескольких цифр при k = 1, 2, 4, 8, 16, 32, 64</span></span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a><span class="co">#          (в заголовке -- накопленная доля дисперсии);</span></span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) нарисуйте среднее изображение и первые 19 главных компонент как</span></span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a><span class="co">#          картинки 8x8 -- «собственные цифры»;</span></span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a><span class="co">#       4) посчитайте, сколько компонент нужно для 90% дисперсии.</span></span></code></pre></div>\n</div>\n<div id="cell014" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпала ли ошибка восстановления с суммой\nотброшенных\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msubsup><mi>σ</mi><mi>j</mi><mn>2</mn></msubsup><annotation encoding="application/x-tex">\\sigma_j^2</annotation></semantics></math>?\nПри каком\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nцифры становятся узнаваемы и как это соотносится с долей объяснённой\nдисперсии? Что изображают первые главные компоненты?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell015" class="cell markdown">\n<hr />\n<h1 id="часть-4-pca-как-предобработка">Часть 4. PCA как\nпредобработка</h1>\n<p>Снижение размерности перед обучением — компромисс: мы теряем часть\nинформации, но уменьшаем разброс (работа 5) и ускоряем обучение. Важно,\nчто PCA <strong>не использует метки</strong> — он максимизирует\nдисперсию, а не разделимость классов, и главное направление вполне может\nоказаться бесполезным для классификации.</p>\n<p>Проверьте: постройте зависимость качества от числа компонент и\nсравните с обучением на всех признаках. Обязательно — с PCA\n<strong>внутри</strong> <code>Pipeline</code> (работа 5, часть 4: иначе\nутечка).</p>\n</div>\n<div id="cell016" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LogisticRegression</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> Pipeline</span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.svm <span class="im">import</span> SVC</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.feature_selection <span class="im">import</span> SelectKBest, f_classif</span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a>X_d, y_d <span class="op">=</span> load_digits(return_X_y<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) для k in [2, 5, 10, 20, 30, 40, 64] оцените скользящим контролем</span></span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a><span class="co">#          качество Pipeline(StandardScaler -&gt; PCA(k) -&gt; классификатор)</span></span>\n<span id="cb7-10"><a href="#cb7-10" aria-hidden="true" tabindex="-1"></a><span class="co">#          для логистической регрессии и SVM с RBF;</span></span>\n<span id="cb7-11"><a href="#cb7-11" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) сравните с обучением без PCA;</span></span>\n<span id="cb7-12"><a href="#cb7-12" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) сравните PCA (не использует метки) с SelectKBest (использует метки)</span></span>\n<span id="cb7-13"><a href="#cb7-13" aria-hidden="true" tabindex="-1"></a><span class="co">#          при одинаковом числе признаков.</span></span>\n<span id="cb7-14"><a href="#cb7-14" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;задача вашего варианта:&quot;</span>, variant[<span class="st">&quot;pca_task&quot;</span>])</span></code></pre></div>\n</div>\n<div id="cell017" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Сколько компонент достаточно, чтобы не\nпотерять качество? Выиграл ли PCA у обучения на всех признаках? Кто\nоказался лучше при малом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\n— PCA или отбор признаков по связи с целью, и почему?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell018" class="cell markdown">\n<hr />\n<h1 id="часть-5-многомерное-шкалирование">Часть 5. Многомерное\nшкалирование</h1>\n<p>Постановка: известны только попарные расстояния\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ρ</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>x</mi><mi>j</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\rho(x_i, x_j)</annotation></semantics></math>,\nнужны координаты\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mover><mi>x</mi><mo accent="true">̃</mo></mover><mi>i</mi></msub><mo>∈</mo><msup><mi>ℝ</mi><mi>k</mi></msup></mrow><annotation encoding="application/x-tex">\\tilde x_i \\in \\mathbb{R}^k</annotation></semantics></math>\nс\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><msub><mover><mi>x</mi><mo accent="true">̃</mo></mover><mi>i</mi></msub><mo>−</mo><msub><mover><mi>x</mi><mo accent="true">̃</mo></mover><mi>j</mi></msub><mo stretchy="false" form="postfix">∥</mo><mo>≈</mo><msub><mi>ρ</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow><annotation encoding="application/x-tex">\\|\\tilde x_i - \\tilde x_j\\| \\approx \\rho_{ij}</annotation></semantics></math>.</p>\n<p>Классическое MDS (замечание в §5 лекции 8): по матрице квадратов\nрасстояний двойным центрированием восстанавливается матрица Грама</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi><mo>=</mo><mi>−</mi><mstyle displaystyle="false"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle><mspace width="0.167em"></mspace><mi>J</mi><msup><mi>D</mi><mrow><mo stretchy="false" form="prefix">(</mo><mn>2</mn><mo stretchy="false" form="postfix">)</mo></mrow></msup><mi>J</mi><mo>,</mo><mspace width="2.0em"></mspace><mi>J</mi><mo>=</mo><mi>I</mi><mo>−</mo><mstyle displaystyle="false"><mfrac><mn>1</mn><mi>ℓ</mi></mfrac></mstyle><mn>𝟏</mn><msup><mn>𝟏</mn><mi>𝖳</mi></msup><mo>,</mo></mrow><annotation encoding="application/x-tex">\nB = -\\tfrac12\\,J D^{(2)} J, \\qquad J = I - \\tfrac1\\ell \\mathbf{1}\\mathbf{1}^{\\mathsf T},\n</annotation></semantics></math></p>\n<p>а координаты берутся из\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nстарших собственных пар\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>B</mi><annotation encoding="application/x-tex">B</annotation></semantics></math>:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mover><mi>X</mi><mo accent="true">̃</mo></mover><mo>=</mo><msub><mi>U</mi><mi>k</mi></msub><msubsup><mi mathvariant="normal">Λ</mi><mi>k</mi><mrow><mn>1</mn><mi>/</mi><mn>2</mn></mrow></msubsup></mrow><annotation encoding="application/x-tex">\\tilde X = U_k \\Lambda_k^{1/2}</annotation></semantics></math>.\nЭто то же вычисление, что и PCA, но для матрицы\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi><msup><mi>X</mi><mi>𝖳</mi></msup></mrow><annotation encoding="application/x-tex">XX^{\\mathsf T}</annotation></semantics></math>\nразмера\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℓ</mi><mo>×</mo><mi>ℓ</mi></mrow><annotation encoding="application/x-tex">\\ell\\times\\ell</annotation></semantics></math>\nвместо\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>.</p>\n<p>Классическая демонстрация: восстановить карту по таблице расстояний\nмежду городами. Ваш вариант: <code>variant[&quot;embedding&quot;]</code>.</p>\n</div>\n<div id="cell019" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> classic_mds(D, k<span class="op">=</span><span class="dv">2</span>):</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Классическое MDS: B = -1/2 J D^2 J, координаты -- из старших собственных пар.&quot;&quot;&quot;</span></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a>cities <span class="op">=</span> [<span class="st">&quot;Калининград&quot;</span>, <span class="st">&quot;Санкт-Петербург&quot;</span>, <span class="st">&quot;Москва&quot;</span>, <span class="st">&quot;Ростов-на-Дону&quot;</span>,</span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a>          <span class="st">&quot;Казань&quot;</span>, <span class="st">&quot;Екатеринбург&quot;</span>, <span class="st">&quot;Новосибирск&quot;</span>, <span class="st">&quot;Иркутск&quot;</span>, <span class="st">&quot;Владивосток&quot;</span>]</span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a>D_km <span class="op">=</span> np.array([</span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a>    [   <span class="dv">0</span>,  <span class="dv">800</span>, <span class="dv">1090</span>, <span class="dv">1650</span>, <span class="dv">1780</span>, <span class="dv">2380</span>, <span class="dv">3760</span>, <span class="dv">5350</span>, <span class="dv">7900</span>],</span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a>    [ <span class="dv">800</span>,    <span class="dv">0</span>,  <span class="dv">635</span>, <span class="dv">1520</span>, <span class="dv">1330</span>, <span class="dv">1780</span>, <span class="dv">3110</span>, <span class="dv">4700</span>, <span class="dv">6400</span>],</span>\n<span id="cb8-11"><a href="#cb8-11" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">1090</span>,  <span class="dv">635</span>,    <span class="dv">0</span>,  <span class="dv">960</span>,  <span class="dv">720</span>, <span class="dv">1420</span>, <span class="dv">2810</span>, <span class="dv">4200</span>, <span class="dv">6430</span>],</span>\n<span id="cb8-12"><a href="#cb8-12" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">1650</span>, <span class="dv">1520</span>,  <span class="dv">960</span>,    <span class="dv">0</span>,  <span class="dv">980</span>, <span class="dv">1750</span>, <span class="dv">3100</span>, <span class="dv">4500</span>, <span class="dv">6800</span>],</span>\n<span id="cb8-13"><a href="#cb8-13" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">1780</span>, <span class="dv">1330</span>,  <span class="dv">720</span>,  <span class="dv">980</span>,    <span class="dv">0</span>,  <span class="dv">730</span>, <span class="dv">2100</span>, <span class="dv">3500</span>, <span class="dv">5750</span>],</span>\n<span id="cb8-14"><a href="#cb8-14" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">2380</span>, <span class="dv">1780</span>, <span class="dv">1420</span>, <span class="dv">1750</span>,  <span class="dv">730</span>,    <span class="dv">0</span>, <span class="dv">1400</span>, <span class="dv">2800</span>, <span class="dv">5050</span>],</span>\n<span id="cb8-15"><a href="#cb8-15" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">3760</span>, <span class="dv">3110</span>, <span class="dv">2810</span>, <span class="dv">3100</span>, <span class="dv">2100</span>, <span class="dv">1400</span>,    <span class="dv">0</span>, <span class="dv">1450</span>, <span class="dv">3700</span>],</span>\n<span id="cb8-16"><a href="#cb8-16" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">5350</span>, <span class="dv">4700</span>, <span class="dv">4200</span>, <span class="dv">4500</span>, <span class="dv">3500</span>, <span class="dv">2800</span>, <span class="dv">1450</span>,    <span class="dv">0</span>, <span class="dv">2500</span>],</span>\n<span id="cb8-17"><a href="#cb8-17" aria-hidden="true" tabindex="-1"></a>    [<span class="dv">7900</span>, <span class="dv">6400</span>, <span class="dv">6430</span>, <span class="dv">6800</span>, <span class="dv">5750</span>, <span class="dv">5050</span>, <span class="dv">3700</span>, <span class="dv">2500</span>,    <span class="dv">0</span>]], dtype<span class="op">=</span><span class="bu">float</span>)</span>\n<span id="cb8-18"><a href="#cb8-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-19"><a href="#cb8-19" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) реализуйте классическое MDS и восстановите карту по D_km;</span></span>\n<span id="cb8-20"><a href="#cb8-20" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) посчитайте среднюю ошибку воспроизведения расстояний;</span></span>\n<span id="cb8-21"><a href="#cb8-21" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) нарисуйте карту с подписями городов и диаграмму Шепарда</span></span>\n<span id="cb8-22"><a href="#cb8-22" aria-hidden="true" tabindex="-1"></a><span class="co">#          (истинное расстояние против расстояния на карте).</span></span>\n<span id="cb8-23"><a href="#cb8-23" aria-hidden="true" tabindex="-1"></a><span class="co">#       Учтите: MDS определяет конфигурацию с точностью до поворота и отражения.</span></span></code></pre></div>\n</div>\n<div id="cell020" class="cell markdown">\n<h3 id="задание-52-mds-против-pca-и-нелинейных-методов">Задание 5.2. MDS\nпротив PCA и нелинейных методов</h3>\n<p>Если расстояния евклидовы, классическое MDS\n<strong>эквивалентно</strong> PCA: обе процедуры используют одни и те же\nненулевые собственные числа\n(<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msubsup><mi>σ</mi><mi>j</mi><mn>2</mn></msubsup><mo>=</mo><mi>ℓ</mi><msub><mi>λ</mi><mi>j</mi></msub></mrow><annotation encoding="application/x-tex">\\sigma_j^2 = \\ell\\lambda_j</annotation></semantics></math>,\nтеорема 8.9). Проверьте это, а затем сравните с методом из вашего\nварианта.</p>\n</div>\n<div id="cell021" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.manifold <span class="im">import</span> MDS, TSNE</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a>X_i, y_i <span class="op">=</span> load_iris(return_X_y<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a>X_is <span class="op">=</span> StandardScaler().fit_transform(X_i)</span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) убедитесь, что при евклидовой метрике классическое MDS и PCA дают</span></span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a><span class="co">#          одну и ту же конфигурацию (сравнивайте матрицы попарных расстояний --</span></span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a><span class="co">#          сами координаты совпадают лишь с точностью до поворота);</span></span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) постройте вложения методом из своего варианта и сравните картинки.</span></span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;метод вашего варианта:&quot;</span>, variant[<span class="st">&quot;embedding&quot;</span>])</span></code></pre></div>\n</div>\n<div id="cell022" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпали ли конфигурации PCA и классического\nMDS? В какой ситуации MDS применим, а PCA — нет? Чем принципиально\nотличается t-SNE от обоих?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell023" class="cell markdown">\n<hr />\n<h1 id="часть-6-сводная-полный-цикл-на-своей-выборке">Часть 6. Сводная:\nполный цикл на своей выборке</h1>\n<p>Заключительное задание курса. На индивидуальной выборке пройдите весь\nпуть, опираясь на работы 1–8:</p>\n<ol>\n<li>предобработка (работа 1) — уже сделана в\n<code>load_personal</code>;</li>\n<li>PCA: визуализация в 2D, выбор числа компонент правилом вашего\nварианта;</li>\n<li>сравнение <strong>трёх моделей из разных семейств</strong>\n(линейная, метрическая или байесовская, ансамблевая) с подбором\nгиперпараметров по скользящему контролю (работа 5) — обязательно всё\nвнутри <code>Pipeline</code>;</li>\n<li>честная финальная оценка на контрольной выборке;</li>\n<li>интерпретация: какие признаки важны и согласуется ли это со здравым\nсмыслом.</li>\n</ol>\n</div>\n<div id="cell024" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.ensemble <span class="im">import</span> RandomForestClassifier</span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.inspection <span class="im">import</span> permutation_importance</span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> roc_auc_score</span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.neighbors <span class="im">import</span> KNeighborsClassifier</span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant)</span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-8"><a href="#cb10-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) при необходимости бинаризуйте цель по медиане обучающей выборки;</span></span>\n<span id="cb10-9"><a href="#cb10-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) PCA: визуализация в первых двух компонентах, выбор k правилом</span></span>\n<span id="cb10-10"><a href="#cb10-10" aria-hidden="true" tabindex="-1"></a><span class="co">#          из variant[&quot;n_components_rule&quot;], график накопленной доли дисперсии;</span></span>\n<span id="cb10-11"><a href="#cb10-11" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) три модели из РАЗНЫХ семейств (линейная, метрическая, ансамблевая)</span></span>\n<span id="cb10-12"><a href="#cb10-12" aria-hidden="true" tabindex="-1"></a><span class="co">#          с подбором гиперпараметров GridSearchCV; PCA -- шагом Pipeline,</span></span>\n<span id="cb10-13"><a href="#cb10-13" aria-hidden="true" tabindex="-1"></a><span class="co">#          чтобы не было утечки;</span></span>\n<span id="cb10-14"><a href="#cb10-14" aria-hidden="true" tabindex="-1"></a><span class="co">#       4) таблица: лучшие параметры, CV AUC и честный AUC на контроле;</span></span>\n<span id="cb10-15"><a href="#cb10-15" aria-hidden="true" tabindex="-1"></a><span class="co">#       5) перестановочная важность признаков лучшей модели + содержательная</span></span>\n<span id="cb10-16"><a href="#cb10-16" aria-hidden="true" tabindex="-1"></a><span class="co">#          интерпретация в выводе.</span></span></code></pre></div>\n</div>\n<div id="cell025" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какая модель победила и насколько уверенно?\nПомог ли PCA? Согласуется ли важность признаков с вашими ожиданиями от\nпредметной области?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell026" class="cell markdown">\n<h2 id="итоги-работы">Итоги работы</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Первая главная компонента — собственный вектор\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>\nс наибольшим собственным числом. Почему именно наибольшим? Приведите\nрассуждение из теоремы 8.2 своими словами.</li>\n<li>Утверждение 8.5 говорит, что\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mo>∑</mo><mi>j</mi></msub><msub><mi>λ</mi><mi>j</mi></msub><mo>=</mo><mrow><mi mathvariant="normal">T</mi><mi mathvariant="normal">r</mi></mrow><mspace width="0.167em"></mspace><mi>C</mi></mrow><annotation encoding="application/x-tex">\\sum_j\\lambda_j = \\mathrm{Tr}\\,C</annotation></semantics></math>.\nКак из этого следует правило выбора числа компонент по доле объяснённой\nдисперсии?</li>\n<li>PCA не использует метки классов. Постройте пример двух классов в\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>ℝ</mi><mn>2</mn></msup><annotation encoding="application/x-tex">\\mathbb{R}^2</annotation></semantics></math>,\nдля которых проекция на первую главную компоненту полностью уничтожает\nразделимость.</li>\n<li>Почему на практике PCA всегда считают через SVD, а не через\nсобственные векторы\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>C</mi><annotation encoding="application/x-tex">C</annotation></semantics></math>?\nСвяжите ответ с работой 2.</li>\n<li>У вас есть только матрица попарных несходств между 200 объектами,\nкоординат нет. Какие методы курса вы можете применить, а какие —\nнет?</li>\n</ol>\n<h3 id="домашнее-задание">Домашнее задание</h3>\n<ol>\n<li><p><strong>Ядровой PCA.</strong> Ядровой трюк из работы 4\nпереносится на PCA: вместо\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>\nберётся центрированная матрица Грама\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mover><mi>K</mi><mo accent="true">̃</mo></mover><mo>=</mo><mi>J</mi><mi>K</mi><mi>J</mi></mrow><annotation encoding="application/x-tex">\\tilde K = JKJ</annotation></semantics></math>,\nа проекции получаются из её старших собственных пар. Реализуйте kernel\nPCA с RBF-ядром и покажите на данных <code>make_circles</code>, что два\nвложенных кольца, неразделимые линейно и неразличимые обычным PCA,\nстановятся линейно разделимыми в первых двух ядровых компонентах.\nСравните со <code>sklearn.decomposition.KernelPCA</code> и исследуйте\nзависимость от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>γ</mi><annotation encoding="application/x-tex">\\gamma</annotation></semantics></math>.</p></li>\n<li><p><strong>Сколько компонент на самом деле нужно.</strong> Правило\n«95 % дисперсии» не связано с качеством решения задачи. Для своей\nвыборки постройте <strong>два</strong> графика в одних осях: накопленную\nдолю дисперсии и качество классификатора по скользящему контролю — оба\nкак функции\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>.\nПокажите, что точки «95 % дисперсии» и «максимум качества» не совпадают,\nи объясните почему. Сформулируйте, в каких задачах разумно выбирать\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>k</mi><annotation encoding="application/x-tex">k</annotation></semantics></math>\nпо дисперсии, а в каких — по качеству итоговой модели.</p></li>\n</ol>\n</div>\n</body>\n</html>\n'}}]);